// v28.xx (cachetag), HIS NOTE (2026-10-16, a picture of CHILL ROW CACHE cut in two by a wall): "text should be on top". The name was
// drawn here with its box, in the depth-sorted world pass, so any wall drawn in front of the box covered it. It is queued now and drawn
// in the world text pass (_wtA) beside the nameplates, after every wall.
if(CACHETAGS.length<48) CACHETAGS.push({t:ct.tag,x:ct.x,y:ct.y-lift-d2-26});

var _wtA=function(){
// v28.xx (cachetag): the named caches, over every wall (queued by the container pass above)
var _ctq=CACHETAGS; CACHETAGS=[];
if(_ctq.length){ wc.font=FS(TYPE.head); wc.textAlign='center';
  for(var _cq=0;_cq<_ctq.length;_cq++){ var _cg=_ctq[_cq]; wc.fillStyle=INK; wc.fillText(_cg.t,_cg.x+1,_cg.y+1); wc.fillStyle='#e6b4ff'; wc.fillText(_cg.t,_cg.x,_cg.y); }
  wc.textAlign='left'; }

check:
{v:'VER',what:'a named cache keeps its name over the walls: the name is drawn in the world text pass after every wall (his picture of CHILL ROW CACHE cut by a wall)',
 run:function(){
   if(typeof __frame!=='function') return 'SKIP: no frame helper';
   var PR=CanvasRenderingContext2D.prototype, of=PR.fillText, g=null, ct=null, i, c, hits=[];
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player) return 'SKIP: no raid';
     for(i=0;i<g.containers.length;i++){ c=g.containers[i]; if(c.cache&&c.tag&&!c.strong){ ct=c; break; } }
     if(!ct) return 'SKIP: no named cache on this map';
     g.player.x=ct.x; g.player.y=ct.y+90;
     PR.fillText=function(s){ if(String(s)===String(ct.tag)) hits.push((/_wtA/).test(String(new Error().stack))); return of.apply(this,arguments); };
     __frame(); __frame();
     PR.fillText=of;
     if(!hits.length) return 'the cache name '+ct.tag+' was not drawn with the player beside it';
     for(i=0;i<hits.length;i++) if(!hits[i]) return 'the cache name '+ct.tag+' is drawn in the depth-sorted world pass, where a wall in front of the box covers it';
     return null;
   } finally {
     PR.fillText=of;
     try{ __endRaid('abandon'); }catch(_e){}
     __topClear();
   } }},
